window.DIGEST_ARCHIVE=window.DIGEST_ARCHIVE||{};window.DIGEST_ARCHIVE["2026-06-09"]={"date":"2026-06-09","dateKR":"2026년 6월 9일","dateEN":"09 June 2026","total":120,"sections":[{"code":"TOP","kTitle":"Section 1. Top News (10건)","eTitle":"Section 1. Top News (10 items)","type":"news","items":[{"code":"TOP-1","title":"Posidonia 2026 개막 — 40,000명·2,227개사 참가","src":"Seatrade Maritime","date":"2026-06-01","kSum":"6월 1일 아테네에서 Posidonia 2026이 개막해 83개국 2,227개 전시업체와 4만여 명의 해운 전문가가 집결했다. 전시 참가 기업 수는 2024년 대비 약 9% 증가했다. 자율운항·환경기술 부스가 대거 등장하며 산업 재편을 상징했다.","eSum":"Posidonia 2026 opened on June 1 in Athens, welcoming more than 40,000 maritime professionals and 2,227 exhibitors from 83 countries — up almost 9% on the 2024 edition. AI and environmental technology featured prominently as the sector recalibrates.","kImp":"글로벌 해운 경기와 기술 트렌드를 가늠하는 최대 지표 행사.","eImp":"The sector's bellwether event for market and technology direction.","url":"https://www.seatrade-maritime.com/event-news/posidonia-2026-takes-centre-stage-as-shipping-recalibrates-amid-global-freedom-of-navigation-challenges"},{"code":"TOP-2","title":"호르무즈 평화협정만으로 선박 복귀 어렵다 — 업계 경고","src":"gCaptain","date":"2026-06","kSum":"Posidonia에서 해운 경영진들은 휴전만으로는 항행의 자유가 회복되지 않는다고 경고했다. 수개월간의 분쟁으로 신뢰가 무너진 상태로, 선박들의 걸프 복귀가 지연되고 있다.","eSum":"Shipping executives at Posidonia warned that freedom of navigation requires more than a ceasefire as confidence remains shattered after months of conflict, delaying vessels' return to the Gulf.","kImp":"중동 리스크 프리미엄이 운임·보험료에 지속 반영될 전망.","eImp":"Middle East risk premiums likely to persist in freight and insurance costs.","url":"https://gcaptain.com/shipping-industry-says-hormuz-peace-deal-alone-wont-bring-ships-back/"},{"code":"TOP-3","title":"컨테이너 운임, 연료비·아시아 항만 혼잡으로 급등","src":"Splash 247","date":"2026-06","kSum":"지난 주 컨테이너 운임이 연료비 상승과 일부 아시아 항만 혼잡으로 급등했다. 희망봉 우회 지속으로 선복 회전율이 떨어지며 시황을 지지하고 있다.","eSum":"Container shipping rates jumped over the past week amid higher fuel costs and congestion at some Asian ports, supported by continued Cape of Good Hope diversions tightening capacity.","kImp":"단기 운임 강세가 화주 물류비 부담으로 전가될 가능성.","eImp":"Short-term rate strength may pass through to shipper logistics costs.","url":"https://splash247.com/category/sector/containers/"},{"code":"TOP-4","title":"HD현대, HMM 발주 확인 — 18년 만 최대 컨선 수주","src":"Maritime Executive","date":"2026","kSum":"HD현대(HD Hyundai)가 HMM의 컨테이너선 발주를 확정하며 18년 만에 최대 규모의 컨테이너선 수주 실적을 기록했다. HMM은 총 20척, 약 28억 달러 규모 신조를 추진 중이다.","eSum":"HD Hyundai confirmed an HMM order, pushing it to its highest containership order intake in 18 years. HMM is pursuing some 20 vessels worth about USD 2.8 billion.","kImp":"한국 조선·해운 동반 성장과 친환경 선대 전환을 견인.","eImp":"Drives Korean shipbuilding-shipping growth and green fleet renewal.","url":"https://maritime-executive.com/article/hd-hyundai-confirms-hmm-order-pushes-to-highest-boxship-orders-in-18-years"},{"code":"TOP-5","title":"IMO MEPC 81 결의안 2026년 발효 — 탈탄소 의무 강화","src":"MarineLink","date":"2026-01","kSum":"2026년 1월 1일부로 IMO MEPC 81 결의안이 발효되어 EEXI·CII 요건이 강화되고 암모니아·메탄올 등 대체연료의 안전 벙커링 지침이 신설됐다.","eSum":"From January 1, 2026 IMO MEPC 81 resolutions tightened EEXI and CII requirements and introduced new guidance for safe bunkering of alternative fuels such as ammonia and methanol.","kImp":"전 선대에 걸친 운항효율·연료전환 압박 가중.","eImp":"Intensifies efficiency and fuel-transition pressure across the fleet.","url":"https://ports.marinelink.com/ports/port/mukilteo/news/imo-mepc-81-resolutions-kick-off-2026-driving-decarbonization-mandates"},{"code":"TOP-6","title":"디지털화에서 자동화로 — 2026년 해운 운영 재편","src":"Maritime Executive","date":"2026","kSum":"AI 발전과 컴플라이언스 도구 확산으로 2026년 해운 디지털화가 큰 도약을 이뤘다. 향후 5년은 선박-육상 간 상호운용성과 AI 생산성 향상이 좌우할 전망이다.","eSum":"Maritime digitalization made a major leap in 2026, driven by AI advances and a surge in compliance tools; the next five years will be defined by ship-shore interoperability and AI productivity gains.","kImp":"운영 효율화의 핵심 동력이 디지털·자동화로 이동.","eImp":"Operational efficiency increasingly hinges on digital and automation.","url":"https://maritime-executive.com/editorials/from-digitalization-to-automation-2026-will-redefine-maritime-operations"},{"code":"TOP-7","title":"ICS 경고 — 신설 IMO '운항금지(Carriage Ban)'로 억류 가능","src":"gCaptain","date":"2026","kSum":"국제해운회의소(ICS)는 신설된 IMO 'Carriage Ban' 규정에 따라 비적합 선박이 억류될 수 있다고 경고했다. 규제 환경 강화로 PSC 리스크가 확대되고 있다.","eSum":"The International Chamber of Shipping warned that ships could face detention under a new IMO 'Carriage Ban', as the tightening regulatory environment widens Port State Control risk.","kImp":"규정 미준수 선박의 억류·운항 차질 위험 증대.","eImp":"Higher detention and disruption risk for non-compliant ships.","url":"https://gcaptain.com/ics-ships-could-face-detention-under-new-imo-carriage-ban/"},{"code":"TOP-8","title":"IMO, MASS 코드 채택 — 자율운항선 규제 현실화","src":"gCaptain","date":"2026","kSum":"IMO가 MASS(자율운항수상선) 코드를 채택하며 자율운항선이 도면 단계에서 규제 대상 현실로 진입했다. 글로벌 표준화의 분기점이 마련됐다.","eSum":"The IMO adopted the MASS Code, moving the autonomous ship from drawing board to regulated reality and marking a turning point for global standardization.","kImp":"자율운항 상용화·클래스 기준 정립을 가속.","eImp":"Accelerates commercialization and class rule development for autonomy.","url":"https://gcaptain.com/imo-adopts-mass-code-the-autonomous-ship-moves-from-drawing-board-to-regulated-reality/"},{"code":"TOP-9","title":"컨테이너선이 대체연료 채택 주도","src":"Seatrade Maritime","date":"2026","kSum":"표준 항로를 운항하는 컨테이너선이 대체연료 조기 채택을 주도할 것으로 전망된다. CMA CGM 등 대형 선사의 메탄올 이중연료선 발주가 이를 뒷받침한다.","eSum":"Container ships are expected to be early adopters of alternative fuels thanks to standard trading routes, with large carriers' methanol dual-fuel orders underpinning the trend.","kImp":"대체연료 수요·벙커링 인프라 확산의 핵심 견인차.","eImp":"Key driver of alternative-fuel demand and bunkering infrastructure.","url":"https://www.seatrade-maritime.com/sustainability-green-technology/container-ships-drive-alternative-fuel-adoption"},{"code":"TOP-10","title":"DetentionTrackr, AI 기반 PSC 인텔리전스 플랫폼 출시","src":"Maritime Executive","date":"2026","kSum":"DetentionTrackr가 전 세계 PSC 억류 데이터를 실시간 인텔리전스로 전환하는 AI 플랫폼을 출시했다. 164건의 글로벌 억류를 추적해 선주의 사전 리스크 관리를 지원한다.","eSum":"DetentionTrackr launched an AI-powered platform turning global PSC detention data into real-time intelligence, tracking 164 global detentions to support proactive owner risk management.","kImp":"데이터 기반 PSC 대응이 새로운 운영 표준으로 부상.","eImp":"Data-driven PSC response emerging as a new operational standard.","url":"https://maritime-executive.com/corporate/detentiontrackr-launches-ai-powered-global-detention-intelligence-platform"}]},{"code":"ACC","kTitle":"Section 2. Accidents (해상 사고, 10건)","eTitle":"Section 2. Accidents (10 items)","type":"accident","items":[{"code":"ACC-1","title":"Golden Star 1 침몰 (인도네시아 해역, 2026-06-05)","src":"Splash 247","date":"2026-06-05","kSum":"67m·2,444 dwt 컨테이너선 Golden Star 1이 6월 5일 20시경 싱가포르 출항 후 수 시간 만에 인도네시아 해역에서 침몰했다. 사고 당시 107개 컨테이너를 적재 중이었으며, 싱가포르 해역 오염 보고는 없었다. 싱가포르 해협·말라카 해협 통항에는 영향이 없었다.","eSum":"The 67-metre, 2,444 dwt boxship Golden Star 1 departed Singapore around 20:00 on June 5 and sank in Indonesian waters hours later while carrying 107 containers. No oil pollution was reported in Singapore waters and Singapore/Malacca Strait traffic was unaffected.","kCause":"복원성 상실 또는 화물 이동 추정 (조사 진행 중).","eCause":"Suspected loss of stability or cargo shift (investigation ongoing).","kLes":"소형 피더선의 적재·복원성 관리 및 SOLAS Ch.II-1 준수 강화 필요.","eLes":"Reinforce loading/stability management and SOLAS Ch.II-1 compliance for small feeders.","url":"https://splash247.com/boxship-goes-down-off-batam/"},{"code":"ACC-2","title":"호르무즈 해협 탱커 2척 충돌·화재","src":"Seatrade Maritime","date":"2026-06","kSum":"호르무즈 해협에서 탱커 2척이 충돌해 화재가 발생했다. 지역 내 군사적 긴장이 고조된 가운데 발생한 사고로, 통항 안전 우려가 재차 부각됐다.","eSum":"Two tankers caught fire after colliding in the Strait of Hormuz, an incident occurring amid heightened regional military tension and renewing concerns over transit safety.","kCause":"혼잡·긴장 해역에서의 견시·교신 미흡 추정.","eCause":"Probable lookout/communication shortfalls in a congested, tense waterway.","kLes":"COLREG 견시 의무 및 고위험 해역 통항계획(SOLAS Ch.V) 철저 이행.","eLes":"Enforce COLREG lookout duties and high-risk passage planning (SOLAS Ch.V).","url":"https://www.seatrade-maritime.com/accidents/tankers-on-fire-after-colliding-in-straits-of-hormuz"},{"code":"ACC-3","title":"제재 대상 러 LNG선 Arctic Metagaz 화재 (몰타 인근)","src":"gCaptain","date":"2026","kSum":"제재 대상 러시아 LNG 운반선 Arctic Metagaz가 지중해 중부에서 화재 후 퇴선했다. 선원들은 리비아 SAR 구역 내 구명정에서 생존 상태로 발견됐다.","eSum":"The sanctioned Russian LNG carrier Arctic Metagaz was abandoned after a reported fire in the central Mediterranean; survivors were found alive in a lifeboat within the Libyan SAR region.","kCause":"화물·기관 구역 화재 추정 (원인 조사 중).","eCause":"Suspected cargo/engine-space fire (cause under investigation).","kLes":"가스운반선 화재 대응·퇴선 훈련 및 ISM 비상절차 점검.","eLes":"Review gas-carrier fire response, abandonment drills and ISM emergency procedures.","url":"https://gcaptain.com/crew-of-sanctioned-russian-lng-carrier-arctic-metagaz-found-alive-after-fire-incident-off-malta/"},{"code":"ACC-4","title":"OSV 화재·퇴선, 남아공 인근 선원 구조","src":"Maritime Executive","date":"2026","kSum":"남아프리카공화국 인근 해역에서 해양작업지원선(OSV)이 화재로 퇴선했고 전 선원이 구조됐다. 화재가 통제되지 않아 선박은 포기됐다.","eSum":"A burning offshore support vessel was abandoned off South Africa with all crew rescued after the fire could not be brought under control.","kCause":"기관실 화재 추정.","eCause":"Suspected engine-room fire.","kLes":"기관실 고정식 소화설비(SOLAS Ch.II-2) 및 화재 초기대응 체계 강화.","eLes":"Strengthen engine-room fixed fire-fighting (SOLAS Ch.II-2) and early response.","url":"https://maritime-executive.com/article/buring-osv-abandoned-and-crew-rescued-off-south-africa"},{"code":"ACC-5","title":"차량 3,000대 적재 화물선 Morning Midas 화재·퇴선 (알래스카 인근)","src":"Marine Insight","date":"2025-06-03","kSum":"차량 3,000여 대를 싣고 중국 옌타이→멕시코 라사로 카르데나스로 향하던 Morning Midas호에서 화재가 발생해 퇴선했다. 알래스카 애덕섬 남서쪽 약 340마일 해상에서 발생했으며 22명 전원 부상 없이 구조됐다.","eSum":"The car carrier Morning Midas, carrying over 3,000 vehicles from Yantai, China to Lázaro Cárdenas, Mexico, was abandoned after a fire some 340 miles SW of Adak Island, Alaska; all 22 crew were rescued unharmed.","kCause":"EV 등 차량 화재 가능성 (PCTC 화재 리스크 부각).","eCause":"Possible vehicle/EV-related fire, highlighting PCTC fire risk.","kLes":"PCTC 차량갑판 화재 탐지·진압 및 EV 운송 안전지침 강화 필요.","eLes":"Enhance PCTC car-deck fire detection/suppression and EV carriage safety guidance.","url":"https://www.marineinsight.com/shipping-news/cargo-ship-carrying-3000-vehicles-abandoned-after-fire-breaks-out-near-alaska/"},{"code":"ACC-6","title":"예멘 인근 홍해 선박 피습, 선원 구조","src":"gCaptain","date":"2026","kSum":"예멘 인근 홍해에서 선박이 피습된 뒤 선원들이 구조됐다. 홍해 항로의 안보 위협이 지속되고 있음을 재확인했다.","eSum":"Crew were rescued in the Red Sea after an attack on a ship near Yemen, reaffirming persistent security threats on the Red Sea route.","kCause":"무력 공격 (드론/미사일 추정).","eCause":"Hostile attack (suspected drone/missile).","kLes":"홍해 통항 시 BMP·ISPS 보안 강화 및 회피항로 검토.","eLes":"Apply BMP/ISPS security measures and consider rerouting for Red Sea transits.","url":"https://gcaptain.com/crew-rescued-in-red-sea-after-attack-on-ship-near-yemen/"},{"code":"ACC-7","title":"인도네시아서 화물선 화재","src":"gCaptain","date":"2026","kSum":"인도네시아 해역에서 화물선에 화재가 발생했다. 동남아 해역의 잇따른 화재 사고로 화물·기관 구역 안전관리 점검 필요성이 제기됐다.","eSum":"A cargo ship caught fire in Indonesian waters, one of a series of Southeast Asian fire incidents prompting reviews of cargo and engine-space safety management.","kCause":"조사 중 (화물/기관 구역 화재 추정).","eCause":"Under investigation (suspected cargo/engine-space fire).","kLes":"열대 해역 운항 선박의 화재탐지·통풍·정비 점검 강화.","eLes":"Tighten fire-detection, ventilation and maintenance checks for tropical operations.","url":"https://gcaptain.com/cargo-ship-catches-fire-in-indonesia/"},{"code":"ACC-8","title":"필리핀 여객선 참사 — 29명 사망, 전 선대 운항정지","src":"gCaptain","date":"2026","kSum":"필리핀에서 여객선 사고로 29명이 사망하고 해당 선사 전 선대가 운항정지됐다. 도서국 연안여객 안전관리 부실이 도마에 올랐다.","eSum":"A Philippines ferry disaster claimed 29 lives and led to the grounding of the operator's entire fleet, spotlighting domestic passenger-ferry safety failures.","kCause":"복원성·과적·운항관리 문제 추정.","eCause":"Suspected stability/overloading and operational-management failures.","kLes":"연안여객선 복원성·정원관리 및 SOLAS 적용 강화 필요.","eLes":"Strengthen domestic ferry stability/passenger-count control and SOLAS application.","url":"https://gcaptain.com/philippines-ferry-disaster-claims-29-lives-as-entire-fleet-grounded/"},{"code":"ACC-9","title":"Wakashio 좌초 3년 만 조사보고서 공개 (모리셔스)","src":"gCaptain","date":"2026","kSum":"2020년 모리셔스 좌초·기름유출을 일으킨 벌크선 Wakashio의 조사보고서가 3년 만에 공개됐다. 항행계획·통신 사용 등 인적요인이 핵심 원인으로 지목됐다.","eSum":"The investigation report into the 2020 grounding and oil spill of the bulk carrier Wakashio off Mauritius was released three years on, citing human factors including passage planning and connectivity use.","kCause":"항로 이탈·견시 소홀 등 인적요인.","eCause":"Human factors — route deviation and inadequate lookout.","kLes":"항행계획 준수, 휴대기기 사용 통제 및 BRM(SOLAS Ch.V) 강화.","eLes":"Enforce passage-plan adherence, device-use control and BRM (SOLAS Ch.V).","url":"https://gcaptain.com/wakashio-report-released-3-years-after-grounding-in-mauritius/"},{"code":"ACC-10","title":"지브롤터 OS 35 충돌 조사 — 강제 도선 필요성 제기","src":"gCaptain","date":"2026","kSum":"지브롤터 OS 35 충돌 사고 조사 결과, 해당 해역의 강제 도선(mandatory pilotage) 도입 필요성이 제기됐다. 정박지 관리·통항관제 개선 권고가 포함됐다.","eSum":"The investigation into the OS 35 collision off Gibraltar revealed a critical need for mandatory pilotage, with recommendations to improve anchorage management and traffic control.","kCause":"정박지 통항관제 및 도선 부재.","eCause":"Inadequate anchorage traffic control and absence of pilotage.","kLes":"혼잡 정박지 도선·VTS 관제 강화 및 묘박 안전절차 정비.","eLes":"Strengthen pilotage/VTS control and anchoring safety procedures in congested anchorages.","url":"https://gcaptain.com/gibraltar-os-35-collision-investigation-reveals-critical-need-for-mandatory-pilotage/"}]},{"code":"PSC","kTitle":"Section 3. PSC (Port State Control, 10건)","eTitle":"Section 3. PSC (Port State Control, 10 items)","type":"news","items":[{"code":"PSC-1","title":"DNV: PSC Q1 2026 억류 리뷰","src":"Hellenic Shipping News","date":"2026-Q1","kSum":"DNV의 2026년 1분기 PSC 리뷰에 따르면 DNV 선대에서 64건의 억류가 기록됐으며 약 84%가 Paris·Tokyo MoU에서 발생했다. 안전관리체계·정비·승무원 숙련도가 핵심 점검 항목으로 유지됐다.","eSum":"DNV's Q1 2026 PSC review recorded 64 detentions across DNV vessels, ~84% in the Paris and Tokyo MoUs, with SMS effectiveness, maintenance and crew familiarity remaining the core focus.","kImp":"기본 항목(SMS·정비·숙련도) 집중 점검 기조 지속.","eImp":"Continued enforcement focus on fundamentals — SMS, maintenance, familiarity.","url":"https://www.hellenicshippingnews.com/dnv-port-state-control-q1-2026-detention-review-and-other-updates/"},{"code":"PSC-2","title":"ABS PSC 리포트 Q1 2026 — 601건 억류","src":"SAFETY4SEA","date":"2026-Q1","kSum":"2026년 1~3월 Paris MoU·Tokyo MoU·USCG 체제에서 총 601건의 선박 억류가 기록됐다. 안전관리·화재안전 준비태세가 여전히 중점 점검 대상이다.","eSum":"Between January and March 2026, 601 vessel detentions were recorded across the Paris MoU, Tokyo MoU and USCG regimes, with safety management and fire-safety readiness in focus.","kImp":"분기 억류 건수 고공행진 — 사전 자체점검 필수.","eImp":"Detentions stay elevated — proactive self-inspection essential.","url":"https://safety4sea.com/abs-psc-report-q1-2026-601-vessel-detentions-from-january-to-march/"},{"code":"PSC-3","title":"USCG, PSC 점검 중 억류 '상당 증가'","src":"Maritime Executive","date":"2026","kSum":"미국 해안경비대(USCG)가 항만국통제 점검 중 억류 건수가 상당히 증가했다고 발표했다. 미주 항만 입항 선박의 결함 관리 부담이 커지고 있다.","eSum":"The USCG reported a 'significant increase' in detentions during port state inspections, raising the deficiency-management burden for ships calling at US ports.","kImp":"미주 입항 전 결함 사전 시정 중요성 증대.","eImp":"Greater need to rectify deficiencies before US port calls.","url":"https://maritime-executive.com/article/uscg-significant-increase-in-detentions-during-port-state-inspections"},{"code":"PSC-4","title":"Paris MoU, 위조 증서 단속 강화","src":"MarineLink","date":"2026","kSum":"Paris MoU가 위조 선박 증서(fraudulent certificates) 단속에 나섰다. 증서 진위 검증 강화로 서류 부실 선박의 적발·억류가 확대될 전망이다.","eSum":"The Paris MoU is cracking down on fraudulent certificates, stepping up verification that is expected to increase detection and detention of vessels with document deficiencies.","kImp":"증서·서류 관리 부실 선박의 억류 리스크 확대.","eImp":"Higher detention risk for vessels with poor certificate/document control.","url":"https://www.marinelink.com/news/paris-mou-tackles-fraudulent-certificates-539880"},{"code":"PSC-5","title":"보고서: 예방가능 PSC 억류 증가세","src":"Maritime Executive","date":"2026","kSum":"전 선대에 걸쳐 예방 가능한 PSC 억류가 증가하고 있다는 보고가 나왔다. 기본적 정비·점검 누락이 반복 억류의 주원인으로 지목됐다.","eSum":"A report finds preventable PSC detentions are increasing across the fleet, with lapses in basic maintenance and checks cited as the main driver of repeat detentions.","kImp":"기초 정비·점검 강화로 억류의 상당수 예방 가능.","eImp":"Many detentions are avoidable through stronger basic maintenance.","url":"https://maritime-executive.com/article/report-preventable-psc-detentions-are-increasing-across-the-fleet"},{"code":"PSC-6","title":"AI 플랫폼, 글로벌 164건 PSC 억류 추적","src":"Marine Insight","date":"2026","kSum":"신규 AI 플랫폼이 연초 이후 전 세계 164건의 PSC 억류를 실시간 인텔리전스로 전환해 추적한다. 선주의 사전 리스크 진단을 지원한다.","eSum":"A new AI platform tracks 164 global PSC detentions since the start of the year, transforming the data into real-time intelligence to support owners' proactive risk assessment.","kImp":"데이터 기반 사전 점검이 PSC 대응의 표준으로.","eImp":"Data-driven pre-screening becoming standard for PSC readiness.","url":"https://www.marineinsight.com/shipping-news/new-ai-platform-tracks-164-global-psc-detentions-transforms-port-state-control-data-into-real-time-intelligence/"},{"code":"PSC-7","title":"International Registries, PSC 억류 트렌드 분석","src":"Hellenic Shipping News","date":"2026","kSum":"International Registries(마셜제도 선적)가 PSC 억류 추세 분석을 공개했다. 기국 차원의 사전 점검·선주 지원 프로그램 확대가 강조됐다.","eSum":"International Registries (Marshall Islands registry) published an analysis of PSC detention trends, emphasizing expanded flag-state pre-screening and owner support programs.","kImp":"기국-선주 협력형 결함 예방 모델 부상.","eImp":"Flag-owner cooperative deficiency-prevention model gaining traction.","url":"https://www.hellenicshippingnews.com/international-registries-port-state-control-detention-trends/"},{"code":"PSC-8","title":"Paris·Tokyo MoU, 화물고박 합동 CIC 예고 (9~11월)","src":"SAFETY4SEA","date":"2026","kSum":"Paris MoU와 Tokyo MoU가 2026년 9월 1일~11월 30일 화물 고박(cargo securing)을 주제로 합동 집중점검캠페인(CIC)을 시행한다. Paris MoU 억류율은 2025년 4.18%로 상승했다.","eSum":"The Paris and Tokyo MoUs will run a joint Concentrated Inspection Campaign on cargo securing from Sep 1 to Nov 30, 2026; the Paris MoU detention rate rose to 4.18% in 2025.","kImp":"하반기 화물 고박 결함 집중 점검 대비 필요.","eImp":"Prepare for H2 focus on cargo-securing deficiencies.","url":"https://safety4sea.com/abs-psc-report-q1-2026-601-vessel-detentions-from-january-to-march/"},{"code":"PSC-9","title":"West Club, PSC 점검 시 유의사항 안내","src":"SAFETY4SEA","date":"2026","kSum":"West P&I Club이 PSC 점검 시 예상 절차와 대비사항을 영상으로 안내했다. 선원의 비상장비 친숙도와 SMS 기록 정비가 핵심으로 제시됐다.","eSum":"The West P&I Club explained what to expect during PSC inspections, highlighting crew familiarity with emergency equipment and well-kept SMS records as key.","kImp":"선원 대비 훈련·기록 정비가 억류 예방의 출발점.","eImp":"Crew drills and record-keeping are the starting point for avoiding detention.","url":"https://safety4sea.com/watch-west-club-explains-what-to-expect-during-psc-inspections/"},{"code":"PSC-10","title":"ICS, 신설 IMO 'Carriage Ban' 억류 가능성 경고","src":"gCaptain","date":"2026","kSum":"ICS는 신설 IMO 'Carriage Ban'에 따라 비적합 선박이 억류될 수 있다고 경고했다. PSC와 연계된 규제 강화로 컴플라이언스 부담이 커지고 있다.","eSum":"The ICS warned that ships could face detention under a new IMO 'Carriage Ban', with PSC-linked regulatory tightening adding to the compliance burden.","kImp":"규제-PSC 연계 강화로 선제적 컴플라이언스 필수.","eImp":"Regulation-PSC linkage makes proactive compliance essential.","url":"https://gcaptain.com/ics-ships-could-face-detention-under-new-imo-carriage-ban/"}]},{"code":"PCTC","kTitle":"Section 4. PCTC / Car Carrier (10건)","eTitle":"Section 4. PCTC / Car Carrier (10 items)","type":"news","items":[{"code":"PCTC-1","title":"PCTC 신조 MV Ocean Explorer 인도","src":"MarineLink","date":"2026","kSum":"신형 PCTC인 MV Ocean Explorer가 인도됐다. 대형 자동차운반선 선대 확충이 이어지며 차량 해상물류 공급능력이 확대되고 있다.","eSum":"The new PCTC MV Ocean Explorer was delivered, continuing the build-up of large car-carrier capacity and expanding seaborne vehicle logistics supply.","kImp":"PCTC 선복 증가로 자동차 물류 병목 완화 기대.","eImp":"Rising PCTC capacity may ease vehicle-logistics bottlenecks.","url":"https://www.marinelink.com/news/pctc-vessel-mv-ocean-explorer-delivered-534161"},{"code":"PCTC-2","title":"Wallenius Wilhelmsen, 이중연료 자동차선 4척 추가 발주","src":"MarineLink","date":"2026","kSum":"Wallenius Wilhelmsen이 9,300 CEU급 메탄올 이중연료 PCTC 4척을 추가 발주했다. MAN B&W 7S60ME-C10.5-LGIM 엔진을 탑재하며 진링조선소에서 2026년 중반부터 인도된다.","eSum":"Wallenius Wilhelmsen ordered four more 9,300 CEU methanol dual-fuel PCTCs with MAN B&W 7S60ME-C10.5-LGIM engines, to be built at Jinling and delivered from mid-2026.","kImp":"메탄올 추진 PCTC 확산으로 친환경 차량운송 가속.","eImp":"Spreads methanol-fuelled PCTCs, accelerating greener vehicle transport.","url":"https://www.marinelink.com/news/wallenius-wilhelmsen-orders-four-dualfuel-511830"},{"code":"PCTC-3","title":"MacGregor, 메탄올 PCTC용 RoRo 설비 공급","src":"Maritime Executive","date":"2026","kSum":"MacGregor가 메탄올 추진 PCTC를 위한 RoRo 하역설비를 공급한다. 친환경 자동차선의 갑판·램프 시스템 고도화가 진행되고 있다.","eSum":"MacGregor is delivering RoRo cargo-handling equipment for methanol-fuelled PCTCs, advancing deck and ramp systems for greener car carriers.","kImp":"친환경 PCTC 기자재 공급망 성장.","eImp":"Growth in the green-PCTC equipment supply chain.","url":"https://maritime-executive.com/corporate/macgregor-roro-equipment-delivery-for-methanol-pure-car-and-truck-carriers"},{"code":"PCTC-4","title":"세계 최대 PCTC Höegh Aurora — 9,100 CEU·EV 대응","src":"SAFETY4SEA","date":"2026","kSum":"세계 최대 PCTC인 Höegh Aurora는 14개 갑판에 최대 9,100 CEU를 적재하며 전 갑판에서 전기차(EV) 운송이 가능하도록 설계됐다. 강화 갑판·램프로 EV 하중에 대응한다.","eSum":"The world's largest PCTC, Höegh Aurora, features 14 decks for up to 9,100 CEU and is designed to carry EVs on all decks with reinforced decks and ramps.","kImp":"EV 대응형 메가 PCTC가 차량운송 표준으로 부상.","eImp":"EV-capable mega-PCTCs becoming the vehicle-transport benchmark.","url":"https://safety4sea.com/do-you-know-the-differences-between-pctcs-and-roro-ropax/"},{"code":"PCTC-5","title":"Sallaum Lines, LNG 이중연료 자동차선 2척 인도","src":"MarineLink","date":"2026","kSum":"Sallaum Lines가 LNG 이중연료 PCTC인 MV Ocean Express·MV Ocean Navigator 2척을 인도받았다. 신흥 선사의 친환경 PCTC 진입이 확대되고 있다.","eSum":"Sallaum Lines took delivery of two LNG dual-fuel PCTCs, the MV Ocean Express and MV Ocean Navigator, marking growing entry of emerging carriers into green PCTCs.","kImp":"LNG 이중연료 PCTC 채택 저변 확대.","eImp":"Broadening adoption of LNG dual-fuel PCTCs.","url":"https://www.marinelink.com/news/sallaum-takes-delivery-lng-dualfueled-car-540038"},{"code":"PCTC-6","title":"Seaspan, LNG 자동차선 최대 10척 발주 — 신시장 진출","src":"gCaptain","date":"2026","kSum":"Seaspan이 중국 상하이 와이가오차오조선에 LNG 이중연료 PCTC 6척(옵션 4척 포함 최대 10척)을 발주하며 자동차선 시장에 진출했다. 메탄올·암모니아 전환 대응 설계를 적용했다.","eSum":"Seaspan ordered up to ten LNG dual-fuel PCTCs (six firm plus four options) at Shanghai Waigaoqiao, entering the car-carrier market with designs ready for methanol/ammonia conversion.","kImp":"리스선사의 진입으로 PCTC 공급경쟁 심화.","eImp":"Lessor entry intensifies PCTC supply competition.","url":"https://gcaptain.com/seaspan-orders-up-to-ten-lng-fueled-car-carriers-expanding-into-new-market/"},{"code":"PCTC-7","title":"China Merchants, 메탄올 자동차선으로 발주 붐 가세","src":"Maritime Executive","date":"2026","kSum":"China Merchants가 메탄올 추진 자동차선을 추가 발주하며 PCTC 발주 붐에 가세했다. 중국 선사·조선의 친환경 자동차선 공급이 빠르게 늘고 있다.","eSum":"China Merchants added methanol-fuelled car carriers to the ordering boom, with Chinese owners and yards rapidly expanding green car-carrier supply.","kImp":"중국발 공급 증가로 글로벌 PCTC 선복 재편.","eImp":"China-led supply growth reshapes global PCTC capacity.","url":"https://maritime-executive.com/article/china-merchants-adds-to-car-carrier-boom-with-methanol-fueled-ships"},{"code":"PCTC-8","title":"中, HMM-현대글로비스 협력 최대 자동차선 진수","src":"Maritime Executive","date":"2026","kSum":"중국 조선소가 HMM-현대글로비스(Hyundai Glovis) 협력 사업의 최대 규모 자동차운반선을 진수했다. 한국 선사 주도 친환경 PCTC 선대 확충이 진행되고 있다.","eSum":"A Chinese yard launched the largest car carrier for the HMM-Hyundai Glovis partnership, advancing Korean-led green PCTC fleet expansion.","kImp":"한·중 협력형 PCTC 확충으로 차량운송 경쟁력 강화.","eImp":"Korea-China PCTC build-up strengthens vehicle-transport competitiveness.","url":"https://maritime-executive.com/article/china-launches-largest-car-carrier-for-hmm-hyundai-glovis-partnership"},{"code":"PCTC-9","title":"자동차선 시장 전망 — 단기 약세 진단","src":"MarineLink","date":"2026","kSum":"자동차운반선 시황 전망이 단기적으로 약세로 진단됐다. 대규모 신조 인도와 수요 둔화 우려가 운임에 하방 압력으로 작용한다.","eSum":"The car-carrier vessel market outlook is assessed as bearish near-term, as heavy newbuild deliveries and demand-slowdown concerns weigh on rates.","kImp":"신조 인도 러시에 따른 선복 과잉 리스크 주의.","eImp":"Watch oversupply risk from the newbuild delivery wave.","url":"https://www.marinelink.com/news/car-carrier-vessel-market-outlook-bearish-520296"},{"code":"PCTC-10","title":"불확실성에 대체연료 선박 발주 둔화","src":"Maritime Executive","date":"2026","kSum":"연료 선택 불확실성과 다양한 접근으로 대체연료 선박(자동차선 포함) 발주가 둔화되고 있다. 선주들이 메탄올·암모니아·LNG 사이에서 관망세를 보인다.","eSum":"Uncertainty and a diverse approach are slowing orders for alternative-fuel vessels, including car carriers, as owners weigh methanol, ammonia and LNG.","kImp":"연료 표준 불확실성이 PCTC 발주 결정 지연 요인.","eImp":"Fuel-standard uncertainty is delaying PCTC ordering decisions.","url":"https://maritime-executive.com/article/uncertainty-and-diverse-approach-slow-orders-for-alternative-fuel-vessels"}]},{"code":"WW","kTitle":"Section 5. Wallenius Wilhelmsen (10건)","eTitle":"Section 5. Wallenius Wilhelmsen (10 items)","type":"news","items":[{"code":"WW-1","title":"Wallenius Wilhelmsen, PCTC 30년 생존연한 운용","src":"Seatrade Maritime","date":"2026","kSum":"Wallenius Wilhelmsen이 변동성 큰 시황 속에서 기존 PCTC를 30년 특별검사(survey)까지 운용하기로 했다. 강한 수요가 노후선 운용을 뒷받침한다.","eSum":"Buoyed by strong demand in a volatile market, Wallenius Wilhelmsen will take PCTCs through their 30-year survey, extending the working life of older tonnage.","kImp":"강세 시황에서 노후선 운용으로 선복 확보.","eImp":"Strong market justifies extending older-vessel service to secure capacity.","url":"https://www.seatrade-maritime.com/cargo/shipping-buoys-wallenius-wilhelmsen-in-volatile-market"},{"code":"WW-2","title":"WW, 2024 연차보고서 — 또 한 번의 기록적 한 해","src":"Hellenic Shipping News","date":"2026","kSum":"Wallenius Wilhelmsen이 2024 연차보고서를 통해 기록적 실적을 발표했다. 견조한 자동차 물동량과 운임이 수익성을 견인했다.","eSum":"Wallenius Wilhelmsen released its 2024 annual report highlighting another record-breaking year, with solid vehicle volumes and rates driving profitability.","kImp":"고수익 기조가 친환경 투자 여력으로 연결.","eImp":"Strong earnings translate into capacity for green investment.","url":"https://www.hellenicshippingnews.com/wallenius-wilhelmsen-releases-2024-annual-report-highlighting-another-record-breaking-year/"},{"code":"WW-3","title":"WW, 신조 자동차선 4척 사상 최대 규모로 업사이징","src":"Seatrade Maritime","date":"2026","kSum":"Wallenius Wilhelmsen이 Shaper Class 신조 자동차선 4척을 사상 최대 규모(12,100 CEU급)로 업사이징했다. 총 14척의 Shaper Class를 2026~2028년 인도받는다.","eSum":"Wallenius Wilhelmsen is upsizing four newbuild car carriers to its largest ever (12,100 CEU), part of a 14-ship Shaper Class program delivering 2026-2028.","kImp":"메가 자동차선 도입으로 규모의 경제 강화.","eImp":"Mega car carriers reinforce economies of scale.","url":"https://www.seatrade-maritime.com/shipyards/wallenius-wilhelmsen-upsizing-four-newbuild-car-carriers-to-largest-ever"},{"code":"WW-4","title":"차량운송 무역 불균형 확대 속 WW 호실적","src":"Lloyd's List","date":"2026","kSum":"Lloyd's List에 따르면 자동차운송 무역 불균형이 확대되는 가운데 Wallenius Wilhelmsen이 견조한 분기 실적을 보고했다. 단기 아시아발 운임이 역사적 고점을 유지한다.","eSum":"Per Lloyd's List, Wallenius Wilhelmsen reported a strong quarter as vehicle-carrier trade imbalance grows, with short-term ex-Asia rates at historic highs.","kImp":"아시아발 강세 운임이 수익 방어선 역할.","eImp":"Strong ex-Asia rates underpin earnings resilience.","url":"https://www.lloydslist.com/LL1154495/Vehicle-carrier-trade-imbalance-growing-as-Wallenius-Wilhelmsen-reports-strong-quarter"},{"code":"WW-5","title":"WW, 분기 사상 최대 실적 기록","src":"gCaptain","date":"2026","kSum":"자동차운송업체 Wallenius Wilhelmsen이 분기 사상 최대 실적을 발표했다. 2026년 선복·물동량의 약 90%를 이미 확보했다.","eSum":"Auto-transport company Wallenius Wilhelmsen reported record quarterly earnings, having already covered about 90% of its 2026 capacity and volumes.","kImp":"높은 계약 커버리지로 실적 가시성 확보.","eImp":"High contract coverage gives strong earnings visibility.","url":"https://gcaptain.com/auto-transport-company-wallenius-wilhelmsen-reports-record-quarterly-earnings/"},{"code":"WW-6","title":"WW, 약 5억 달러 계약 연장 — 탈탄소 추진 강화","src":"gCaptain","date":"2026","kSum":"Wallenius Wilhelmsen이 2건의 전략 운송계약을 약 5억 달러 규모로 연장했다. 두 계약 모두 2040 넷제로 목표에 맞춘 환경 목표와 다중연료 BAF 메커니즘을 포함한다.","eSum":"Wallenius Wilhelmsen secured nearly USD 500M in extensions on two strategic contracts, both incorporating 2040 net-zero-aligned targets and multi-fuel BAF mechanisms.","kImp":"장기계약에 탈탄소 비용 분담 구조 내재화.","eImp":"Embeds decarbonization cost-sharing into long-term contracts.","url":"https://gcaptain.com/wallenius-wilhelmsen-secures-nearly-500m-in-contract-extensions-reinforcing-decarbonization-push/"},{"code":"WW-7","title":"Equinor, WW에 바이오메탄올 공급","src":"MarineLink","date":"2026","kSum":"Equinor가 2026년 말부터 Wallenius Wilhelmsen에 바이오메탄올을 공급한다. 제브뤼헤·안트베르펜 항에서 신규 메탄올 이중연료선에 사용될 예정이다.","eSum":"Equinor will supply bio-methanol to Wallenius Wilhelmsen from late 2026 for its new dual-fuel methanol vessels at the ports of Zeebrugge and Antwerp.","kImp":"연료 공급계약 확보로 메탄올 추진 실행력 제고.","eImp":"Secured fuel supply boosts methanol-propulsion execution.","url":"https://www.marinelink.com/news/equinor-supply-biomethanol-wallenius-536826"},{"code":"WW-8","title":"WW, 예테보리 RoRo 터미널 12년 운영권 확보","src":"Seatrade Maritime","date":"2026-02","kSum":"Wallenius Wilhelmsen이 스웨덴 예테보리항 차량·RoRo 터미널의 12년 운영권을 확보해 2026년 2월부터 운영을 개시한다. 터미널 사업 확대로 통합 물류망을 강화한다.","eSum":"Wallenius Wilhelmsen won a 12-year concession to operate the Port of Gothenburg's vehicle and RoRo terminal from February 2026, expanding its integrated logistics network.","kImp":"해상-터미널 통합으로 가치사슬 장악력 확대.","eImp":"Sea-terminal integration deepens value-chain control.","url":"https://www.seatrade-maritime.com/terminals/wallenius-wilhelmsen-wins-12-year-gothenburg-ro-ro-terminal-contract"},{"code":"WW-9","title":"WW, 탈탄소 중심 조직개편 단행","src":"gCaptain","date":"2026","kSum":"Wallenius Wilhelmsen이 탈탄소에 초점을 맞춘 새로운 조직 구조를 공개했다. 2027년 무배출 종단 서비스 도입을 목표로 Orcelle Accelerator 태스크포스를 운영한다.","eSum":"Wallenius Wilhelmsen revealed a new company structure focused on decarbonization, running the Orcelle Accelerator task force toward zero-emission end-to-end services by 2027.","kImp":"조직·전략을 탈탄소 전환에 정렬.","eImp":"Aligns organization and strategy around the energy transition.","url":"https://gcaptain.com/wallenius-wilhelmsen-reveals-new-company-structure-focused-on-decarbonization/"},{"code":"WW-10","title":"Svitzer·WW, EcoTow 협약 체결 — Scope 3 감축","src":"MarineLink","date":"2026","kSum":"Wallenius Wilhelmsen이 Svitzer와 글로벌 EcoTow 협약을 체결해 Scope 3 배출 감축을 추진한다. 호주·영국·스칸디나비아 등 주요 시장의 예선 작업이 대상이다.","eSum":"Wallenius Wilhelmsen signed a global EcoTow agreement with Svitzer to cut Scope 3 emissions, covering tug jobs in key markets such as Australia, the UK and Scandinavia.","kImp":"공급망(Scope 3) 배출까지 감축 범위 확대.","eImp":"Extends emissions cuts into the supply chain (Scope 3).","url":"https://www.marinelink.com/news/svitzer-wallenius-wilhelmsen-sign-ecotow-524651"}]},{"code":"EE","kTitle":"Section 6. Energy Efficiency (10건)","eTitle":"Section 6. Energy Efficiency (10 items)","type":"news","items":[{"code":"EE-1","title":"IMO MEPC 81, 2026년 탈탄소 의무 본격화","src":"MarineLink","date":"2026-01","kSum":"2026년부터 강화된 EEXI·CII 요건과 암모니아·메탄올 안전 벙커링 지침이 발효됐다. CII D·E 등급 2년 연속 선박은 의무 시정조치 대상이다.","eSum":"From 2026, tightened EEXI and CII requirements and ammonia/methanol safe-bunkering guidance took effect; ships rated D or E for two consecutive years face mandatory corrective action.","kImp":"운항효율 등급 관리가 자산가치와 직결.","eImp":"Efficiency ratings now directly affect asset value.","url":"https://ports.marinelink.com/ports/port/mukilteo/news/imo-mepc-81-resolutions-kick-off-2026-driving-decarbonization-mandates"},{"code":"EE-2","title":"컨테이너선이 대체연료 채택 주도","src":"Seatrade Maritime","date":"2026","kSum":"표준 항로의 컨테이너선이 대체연료 조기 채택을 주도하며 수요를 견인할 전망이다. 메탄올·LNG 이중연료 발주가 이를 뒷받침한다.","eSum":"Container ships are leading early adoption of alternative fuels and are expected to drive demand, supported by methanol and LNG dual-fuel orders.","kImp":"대체연료 수요 견인 부문으로 컨선 부각.","eImp":"Boxships emerge as the demand engine for alternative fuels.","url":"https://www.seatrade-maritime.com/sustainability-green-technology/container-ships-drive-alternative-fuel-adoption"},{"code":"EE-3","title":"넷제로 항해 — 탈탄소 의무와 그린연료 경쟁","src":"MarineLink","date":"2026","kSum":"탈탄소 의무 강화로 그린연료 확보 경쟁이 가열되고 있다. 메탄올·암모니아·바이오연료 공급망 구축이 선사 경쟁력의 관건으로 부상했다.","eSum":"Tightening decarbonization mandates are intensifying the green-fuels race, making methanol, ammonia and biofuel supply chains central to carrier competitiveness.","kImp":"연료 공급망 선점이 탈탄소 경쟁 우위 좌우.","eImp":"Securing fuel supply chains decides decarbonization advantage.","url":"https://www.marinelink.com/articles/maritime/sailing-to-netzero-the-decarbonization-mandate-and-the-green-103810"},{"code":"EE-4","title":"MSC, 메탄올 이중연료 컨선 10척 발주","src":"MarineLink","date":"2026","kSum":"MSC가 메탄올 이중연료 컨테이너선 10척을 발주하며 친환경 선대를 확대했다. 대형 선사들의 메탄올 추진 전환이 가속되고 있다.","eSum":"MSC ordered ten dual-fuel methanol containerships, expanding its green fleet as major carriers accelerate the shift to methanol propulsion.","kImp":"대형 선사 발주가 메탄올 공급·수요를 확대.","eImp":"Major-carrier orders scale up methanol supply and demand.","url":"https://ports.marinelink.com/ports/port/richland/news/msc-orders-ten-dual-fuel-methanol-containerships-expanding-green-fleet"},{"code":"EE-5","title":"세계 최초 풍력·수소 무배출 화물선","src":"Maritime Executive","date":"2026","kSum":"풍력과 수소를 결합한 세계 최초의 무배출 화물선 프로젝트가 추진된다. 2개의 대형 로터세일과 수소 연료 내연기관을 결합한 'With Orca' 개념이 대표적이다.","eSum":"A world-first zero-emission cargo ship combining wind and hydrogen is advancing, exemplified by the 'With Orca' concept pairing two large rotor sails with a hydrogen-fuelled engine.","kImp":"풍력+수소 하이브리드가 무배출 선박의 한 축.","eImp":"Wind-plus-hydrogen hybrids form one path to zero-emission ships.","url":"https://maritime-executive.com/article/world-s-first-zero-emission-wind-and-hydrogen-power-cargo-ship"},{"code":"EE-6","title":"MOL, 수소 생산 돛 추진선 'Wind Hunter' 추진","src":"Maritime Executive","date":"2026","kSum":"MOL이 돛으로 추진하며 수소를 생산·저장하는 'Wind Hunter' 선박 건조를 진행한다. 바람이 약할 때는 저장 수소로 연료전지를 가동해 추진한다.","eSum":"MOL is moving forward with its sail-powered 'Wind Hunter' ship that produces and stores hydrogen, using stored hydrogen to power a fuel cell when wind is weak.","kImp":"풍력-수소 변환형 자가발전 추진 개념 실증.","eImp":"Demonstrates wind-to-hydrogen self-generating propulsion.","url":"https://maritime-executive.com/article/mol-moves-forward-with-wind-hunter-sail-powered-ship-that-produces-hydrogen"},{"code":"EE-7","title":"Fincantieri, 세계 최초 수소 크루즈선 Viking Libra 진수","src":"Maritime Executive","date":"2026-03","kSum":"Fincantieri가 2026년 3월 세계 최초 수소 추진 크루즈선으로 홍보되는 Viking Libra(54,300 GT)를 진수했다. 액화수소와 연료전지 추진을 적용한다.","eSum":"In March 2026 Fincantieri floated the Viking Libra (54,300 GT), billed as the world's first hydrogen-powered cruise ship, using liquefied hydrogen and fuel-cell propulsion.","kImp":"여객선 부문의 수소 추진 상용화 신호탄.","eImp":"A milestone for hydrogen propulsion in the passenger segment.","url":"https://maritime-executive.com/article/fincantieri-floats-for-viking-first-hydrogen-powered-cruise-ship"},{"code":"EE-8","title":"불확실성에 대체연료 선박 발주 둔화","src":"Maritime Executive","date":"2026","kSum":"연료 선택 불확실성으로 대체연료 선박 발주가 둔화되고 있다. 선주들이 메탄올·암모니아·LNG 간 표준 정립을 기다리며 관망세를 보인다.","eSum":"Uncertainty is slowing alternative-fuel vessel orders as owners await fuel-standard clarity across methanol, ammonia and LNG.","kImp":"연료 표준 불확실성이 투자 의사결정의 최대 변수.","eImp":"Fuel-standard uncertainty is the key variable in investment decisions.","url":"https://maritime-executive.com/article/uncertainty-and-diverse-approach-slow-orders-for-alternative-fuel-vessels"},{"code":"EE-9","title":"DNV: 2025년 LNG 추진 컨선이 대체연료 발주 견인","src":"MarineLink","date":"2026","kSum":"DNV에 따르면 2025년 대체연료 선박 발주를 LNG 추진 컨테이너선이 떠받쳤다. LNG가 단기 전환연료로서 여전히 핵심 역할을 하고 있다.","eSum":"DNV found LNG-fuelled container ships propped up alternative-fuel orders in 2025, with LNG still playing a key role as a near-term transition fuel.","kImp":"LNG가 중기 전환연료로 입지 유지.","eImp":"LNG retains its role as a medium-term transition fuel.","url":"https://www.marinelink.com/news/lngfueled-container-ships-prop-534268"},{"code":"EE-10","title":"MOL, 수소·바이오연료 배터리 하이브리드선 진수","src":"Maritime Executive","date":"2026","kSum":"MOL이 수소와 바이오연료로 구동되는 배터리 하이브리드 선박을 진수했다. 다중 청정연료·배터리 조합으로 연안 운항의 배출 저감을 추진한다.","eSum":"MOL launched a battery-hybrid vessel powered by hydrogen and biofuel, combining multiple clean fuels with batteries to cut emissions in coastal operations.","kImp":"다중연료·배터리 하이브리드의 실증 확대.","eImp":"Expands real-world testing of multi-fuel battery hybrids.","url":"https://maritime-executive.com/article/mol-launches-battery-hybrid-vessel-powered-by-hydrogen-and-biofuel"}]},{"code":"DIG","kTitle":"Section 7. Digitalization (10건)","eTitle":"Section 7. Digitalization (10 items)","type":"news","items":[{"code":"DIG-1","title":"해양 사이버리스크의 '제3시대' 진입","src":"MarineLink","date":"2026","kSum":"IT-OT 융합으로 선박이 사실상 '떠다니는 데이터센터'가 되며 해양 사이버리스크가 새로운 국면(제3시대)에 진입했다. 공격 표면이 광범위하게 확대됐다.","eSum":"IT/OT convergence has turned ships into 'floating data centers', ushering maritime cyber risk into a 'third era' with a vastly expanded attack surface.","kImp":"OT 보안·선박 사이버 거버넌스 투자 시급.","eImp":"Urgent need for OT security and shipboard cyber governance.","url":"https://www.marinelink.com/news/navigating-third-era-maritime-cyber-risk-536724"},{"code":"DIG-2","title":"AI가 해운 사이버 공격 위험 키운다 — 신규 데이터","src":"Hellenic Shipping News","date":"2026","kSum":"신규 데이터에 따르면 조직의 87%가 AI 관련 취약성을 가장 빠르게 증가하는 위험으로 인식한다. 해운사들이 사이버 책임 정의보다 빠르게 AI를 도입하고 있다.","eSum":"New data shows 87% of organizations view AI-related vulnerabilities as the fastest-growing risk, with shipping companies deploying AI faster than they define cyber accountability.","kImp":"AI 도입 속도와 보안 거버넌스 간 격차 해소 필요.","eImp":"Close the gap between AI adoption pace and security governance.","url":"https://www.hellenicshippingnews.com/ai-technology-is-placing-the-maritime-industry-at-greater-risk-of-a-cyber-attack-reveals-new-data/"},{"code":"DIG-3","title":"디지털·데이터·AI가 만드는 새로운 안전 보호 방정식","src":"Maritime Executive","date":"2026","kSum":"AI의 실시간 인사이트·리스크 평가·행동 모니터링이 위험 탐지를 개선하고 있다. 디지털 트윈이 현 성능 표현과 미래 예측에 활용된다.","eSum":"AI's real-time insights, risk assessment and behavior monitoring are improving hazard detection, with digital twins used to represent current performance and project forward.","kImp":"데이터·AI 기반 예방안전 모델 확산.","eImp":"Spread of data/AI-driven preventive-safety models.","url":"https://www.maritime-executive.com/corporate/digitalization-data-ai-create-an-equation-for-new-safety-protection"},{"code":"DIG-4","title":"디지털화에서 자동화로 — 2026년 운영 재편","src":"Maritime Executive","date":"2026","kSum":"AI가 생성형에서 에이전트형·물리형으로 빠르게 진화하며 자율운항·최적 선대운영으로 영역을 확장하고 있다. 선박-육상 상호운용성이 핵심 화두다.","eSum":"As AI moves from generative to agentic and physical models, it is expanding into autonomous navigation and optimal fleet operations, with ship-shore interoperability the key theme.","kImp":"AI 진화가 운영 자동화의 범위를 급속 확대.","eImp":"AI's evolution rapidly widens the scope of operational automation.","url":"https://maritime-executive.com/editorials/from-digitalization-to-automation-2026-will-redefine-maritime-operations"},{"code":"DIG-5","title":"IMO, MASS 코드 채택 — 자율운항 규제 현실화","src":"gCaptain","date":"2026","kSum":"IMO가 MASS 코드를 채택하며 자율운항선이 규제 대상 현실로 진입했다. 소프트웨어 무결성·AI·원격제어에 대한 클래스 평가 방법론 개발이 과제로 남았다.","eSum":"The IMO adopted the MASS Code, making autonomy a regulated reality; class societies now face the challenge of developing assessment methods for software integrity, AI and remote control.","kImp":"자율운항 클래스·검사체계 정립 가속.","eImp":"Accelerates development of autonomy class and survey frameworks.","url":"https://gcaptain.com/imo-adopts-mass-code-the-autonomous-ship-moves-from-drawing-board-to-regulated-reality/"},{"code":"DIG-6","title":"세계 최초, 자율운항선의 항행정보 판독 연구 착수","src":"Marine Insight","date":"2026","kSum":"영국 수로국(UKHO)과 Marine AI가 자율운항선(MASS)이 공식 항행정보를 읽고 해석·실행하도록 하는 세계 최초 연구를 시작했다. 2026년 봄 실해역 시연이 예정됐다.","eSum":"The UK Hydrographic Office and Marine AI launched a world-first programme to enable MASS to read, interpret and act on official navigational information, with a live on-water demo set for spring 2026.","kImp":"자율운항의 항행정보 활용 표준화 진전.","eImp":"Advances standardization of navigational-data use for autonomy.","url":"https://www.marineinsight.com/shipping-news/world-first-project-launched-to-teach-autonomous-ships-to-read-critical-navigation-data/"},{"code":"DIG-7","title":"8개국, 자율운항선 표준 정렬 위해 협력","src":"Seatrade Maritime","date":"2026","kSum":"8개국이 자율운항선 표준 정렬을 위해 손을 잡았다. 국경을 넘는 자율운항 상호운용성과 규제 조화를 추진한다.","eSum":"Eight nations joined hands to align standards for autonomous ships, pursuing cross-border interoperability and regulatory harmonization for MASS.","kImp":"국가 간 표준 정렬로 자율운항 상용화 촉진.","eImp":"Cross-national alignment speeds MASS commercialization.","url":"https://www.seatrade-maritime.com/technology/eight-nations-join-hands-align-standards-autonomous-ships"},{"code":"DIG-8","title":"세계 최초 무인 여객선 'Olympia Dream Seto' 운항","src":"Marine Insight","date":"2026","kSum":"일본 세토내해 장거리 항로에서 자동항법(MASS) 여객선 Olympia Dream Seto가 운항을 시작했다. 레벨 4 자율로 무인 상태에서 정적·동적 장애물 회피가 가능하다.","eSum":"The Olympia Dream Seto, the world's first passenger ship with automatic navigation (MASS) on a long-distance route in Japan's Seto Inland Sea, operates at Level 4 autonomy, avoiding moving and stationary objects without an onboard operator.","kImp":"여객 부문 고수준 자율운항 실증 진입.","eImp":"High-level autonomy enters real passenger operations.","url":"https://www.marineinsight.com/know-more/worlds-first-autonomous-passenger-ship-sailing-without-captain-or-crew/"},{"code":"DIG-9","title":"적대적 바다 — AI와 진화하는 해양 사이버 위협","src":"MarineLink","date":"2026","kSum":"AI가 해양 사이버 위협을 빠르게 진화시키고 있다. 전통적 보안 대응 시간 창이 붕괴되며 능동적 방어 체계 구축이 요구된다.","eSum":"AI is rapidly evolving the maritime cyber threat, collapsing the traditional security response window and demanding proactive defense.","kImp":"위협 진화 속도에 맞춘 능동적 사이버 방어 필요.","eImp":"Proactive cyber defense needed to match the threat's pace.","url":"https://www.marinelink.com/news/adversarial-seas-ai-evolving-cyber-threat-513526"},{"code":"DIG-10","title":"싱가포르 MPA·NYK, 항만-자율운항선 연계 시험","src":"Marine Insight","date":"2026","kSum":"싱가포르 해사항만청(MPA)과 NYK·MTI가 항만 시스템과 자율운항선의 상호운용성을 시험하는 항만 간 합동 워크숍을 진행했다. MPA의 선박교통정보시스템(VTIS) 연동을 검증했다.","eSum":"Singapore's MPA, NYK and MTI ran a joint port-to-port workshop testing interoperability between autonomous vessels and port systems, including MPA's Vessel Traffic Information System.","kImp":"스마트포트-자율선 연계가 차세대 항만 운영 핵심.","eImp":"Smart-port/autonomous-vessel linkage is central to next-gen ports.","url":"https://www.seatrade-maritime.com/technology/eight-nations-join-hands-align-standards-autonomous-ships"}]},{"code":"TECH","kTitle":"Section 8. Ship Manager Technical Team (10건)","eTitle":"Section 8. Ship Manager Technical Team (10 items)","type":"news","items":[{"code":"TECH-1","title":"Techcross, 탱커 기관실 BWMS 레트로핏","src":"MarineLink","date":"2026","kSum":"Techcross가 기존 탱커의 기관실에 BWMS를 최초로 설치하는 데 성공했다. 2016년 한국 특허 'Engine Room Solution'으로 구매·설치 비용을 20% 이상 절감할 수 있다.","eSum":"Techcross successfully installed a BWMS in an existing tanker's engine room for the first time; its 2016 Korean-patented 'Engine Room Solution' can cut purchase and installation costs by over 20%.","kImp":"기관실 설치형 BWMS로 레트로핏 비용 절감.","eImp":"Engine-room BWMS retrofits reduce installation costs.","url":"https://www.marinelink.com/news/techcross-retrofits-bwms-tankers-engine-505457"},{"code":"TECH-2","title":"레트로핏 BWMS용 기관실 솔루션 성공 사례","src":"Hellenic Shipping News","date":"2026","kSum":"기존선 BWMS 레트로핏에 기관실(E/R) 솔루션을 적용한 성공 사례가 보고됐다. 공간 제약이 큰 노후선의 환경설비 설치 난제를 해소한다.","eSum":"A successful engine-room solution for BWMS retrofit was reported, addressing the challenge of installing environmental equipment on space-constrained older ships.","kImp":"노후선 BWMS 설치 공간 문제 해법 제시.","eImp":"Offers a solution to BWMS space constraints on older ships.","url":"https://www.hellenicshippingnews.com/successful-e-r-solution-for-bwms-on-retrofit/"},{"code":"TECH-3","title":"Scorpio 탱커, BWMS 레트로핏에 Choice Ballast 선정","src":"MarineLink","date":"2026","kSum":"Scorpio 탱커가 BWMS 레트로핏 공급사로 Choice Ballast Solutions를 선정했다. 대형 탱커 선대의 환경규제 대응 정비가 본격화되고 있다.","eSum":"Scorpio Tankers selected Choice Ballast Solutions for its BWMS retrofits, as large tanker fleets ramp up environmental-compliance refits.","kImp":"선대 단위 BWMS 표준화로 정비 효율 제고.","eImp":"Fleet-wide BWMS standardization improves refit efficiency.","url":"https://www.marinelink.com/news/choice-ballast-solutions-chosen-scorpio-440656"},{"code":"TECH-4","title":"선박 레트로핏 리스크 관리 — 설계·실행·검증","src":"Hellenic Shipping News","date":"2026","kSum":"선박 레트로핏 리스크를 줄이기 위해 설계·실행·검증 3단계 접근이 강조됐다. 사전 엔지니어링과 검증이 공기·비용 초과를 막는 핵심이다.","eSum":"A three-step design, execution and verification approach is emphasized to de-risk ship retrofits, with upfront engineering and verification key to avoiding schedule and cost overruns.","kImp":"레트로핏 사전 엔지니어링이 리스크 관리의 핵심.","eImp":"Upfront engineering is central to retrofit risk management.","url":"https://www.hellenicshippingnews.com/how-to-derisk-ship-retrofits-design-execution-and-verification/"},{"code":"TECH-5","title":"BWM 레트로핏 7단계 가이드","src":"SAFETY4SEA","date":"2026","kSum":"SAFETY4SEA가 평형수처리장치(BWM) 레트로핏을 위한 7단계 가이드를 제시했다. 사전조사·설계·설치·시운전 절차의 체계화를 권고한다.","eSum":"SAFETY4SEA outlined a seven-step guide for BWM retrofits, recommending a structured process across survey, design, installation and commissioning.","kImp":"표준화된 절차로 레트로핏 품질·일정 관리.","eImp":"Standardized steps improve retrofit quality and scheduling.","url":"https://safety4sea.com/7-steps-bwm-retrofits/"},{"code":"TECH-6","title":"레트로핏 수요 폭증에 수리조선소 만선","src":"Hellenic Shipping News","date":"2026","kSum":"환경규제 대응 레트로핏 수요가 급증하며 수리조선소가 일감으로 가득 찼다. BWMS·스크러버·이중연료 개조 수요가 도크 가용성을 압박한다.","eSum":"Surging compliance-driven retrofit demand has filled ship repair yards, with BWMS, scrubber and dual-fuel conversion work squeezing dock availability.","kImp":"도크 슬롯 확보 경쟁 심화 — 사전 계획 필수.","eImp":"Competition for dock slots intensifies — plan ahead.","url":"https://www.hellenicshippingnews.com/ship-repair-yards-fill-up-on-retrofitting-rush/"},{"code":"TECH-7","title":"PMS에 반드시 포함할 20가지 항목","src":"Marine Insight","date":"2026","kSum":"계획정비체계(PMS)에 포함해야 할 20가지 핵심 항목이 정리됐다. 운전시간(4000/8000hr) 및 캘린더 주기 기반 정비 관리가 강조된다.","eSum":"Twenty essential items to include in a Planned Maintenance System were outlined, emphasizing running-hour (4000/8000 hr) and calendar-based maintenance management.","kImp":"PMS 표준화로 기관 신뢰성·검사 대비 강화.","eImp":"PMS standardization boosts machinery reliability and survey readiness.","url":"https://www.marineinsight.com/guidelines/20-things-that-should-be-included-in-the-planned-maintenance-system/"},{"code":"TECH-8","title":"선박 입거(드라이도크) 종합 가이드","src":"Marine Insight","date":"2026","kSum":"SOLAS상 모든 상선은 5년 내 2회 입거 선체검사가 요구되며 36개월 이내 중간검사가 필요하다. Graving dock가 레트로핏·개조에 유리하다.","eSum":"Under SOLAS, all merchant vessels require two dry-dock hull surveys within five years plus an intermediate survey within 36 months; graving docks are advantageous for retrofits.","kImp":"입거 일정·검사주기 통합 관리로 비용 최적화.","eImp":"Integrated dry-dock and survey scheduling optimizes cost.","url":"https://www.marineinsight.com/guidelines/dry-dock-types-of-dry-docks-requirements-for-dry-dock/"},{"code":"TECH-9","title":"선박 스크러버 시스템 가이드","src":"Marine Insight","date":"2026","kSum":"하이브리드 스크러버는 개방형·폐쇄형 운전이 모두 가능하다. 외해에서는 개방형, ECA·항만에서는 폐쇄형으로 운전해 배출규제에 대응한다.","eSum":"Hybrid scrubbers can run open- and closed-loop — open loop at sea and closed loop in ECA zones and ports — to meet emission rules.","kImp":"운항해역별 스크러버 운전모드 관리 중요.","eImp":"Managing scrubber modes by sea area is important for compliance.","url":"https://www.marineinsight.com/scrubber-system-on-ship/"},{"code":"TECH-10","title":"선상 정비작업 수행 방법","src":"Marine Insight","date":"2026","kSum":"선상 정비작업의 계획·실행·기록 절차가 정리됐다. 운전시간·상태기반 정비와 안전작업허가(PTW) 체계의 연계가 강조된다.","eSum":"Onboard maintenance planning, execution and recording were outlined, emphasizing the link between running-hour/condition-based maintenance and the permit-to-work system.","kImp":"PTW 연계 정비로 안전·신뢰성 동시 확보.","eImp":"PTW-linked maintenance secures both safety and reliability.","url":"https://www.marineinsight.com/guidelines/how-maintenance-work-is-done-onboard-a-ship/"}]},{"code":"HR","kTitle":"Section 9. Marine HR (10건)","eTitle":"Section 9. Marine HR (10 items)","type":"news","items":[{"code":"HR-1","title":"해양인재 육성 프로그램 — 승무원 위기 대응","src":"SAFETY4SEA","date":"2026","kSum":"STCW 요건에 완전 부합하는 해양인재 육성 프로그램이 장기 전문성 개발에 초점을 두고 추진된다. 심화되는 승무원 위기에 대응한 체계적 양성을 목표로 한다.","eSum":"A Maritime Talent Development Program fully aligned with STCW focuses on long-term professional development to navigate the deepening crew crisis.","kImp":"체계적 인재양성이 인력난 완화의 핵심.","eImp":"Structured talent development is key to easing the labour crunch.","url":"https://safety4sea.com/cm-maritime-talent-development-program-navigating-the-crew-crisis/"},{"code":"HR-2","title":"선원 임금 상승에도 정신건강·복지 문제 지속","src":"Marine Insight","date":"2026","kSum":"선원 임금이 일부 직급에서 2023년 대비 최대 10% 상승했으나 정신건강·복지 만족도는 하락했다. 식수·식량 부족(25%), 임금 체불(35%) 등 문제가 보고됐다.","eSum":"Seafarer salaries rose up to 10% versus 2023 for some ranks, yet mental-health and welfare satisfaction fell; 25% reported lack of food/water and 35% reported late pay.","kImp":"임금 인상만으로는 복지·정신건강 개선 한계.","eImp":"Pay rises alone cannot fix welfare and mental-health gaps.","url":"https://www.marineinsight.com/seafarer-salaries-continue-to-rise-but-mental-health-welfare-issues-persist-reports/"},{"code":"HR-3","title":"MLC 20주년 — 휴식시간 위기와 선원 부족","src":"Seatrade Maritime","date":"2026","kSum":"해사노동협약(MLC) 발효 20주년을 맞아 근로·휴식시간 준수 위기와 선원 부족이 핵심 과제로 부각됐다. 피로관리와 정원확보의 균형이 시급하다.","eSum":"At MLC's 20th anniversary, hours-of-work-and-rest compliance and seafarer shortage emerged as core challenges, underscoring the urgent need to balance fatigue management and manning.","kImp":"피로관리-정원확보의 구조적 균형이 관건.","eImp":"Structural balance of fatigue management and manning is critical.","url":"https://www.seatrade-maritime.com/crewing/mlc-at-20-hours-of-work-and-rest-crisis-and-seafarer-shortage"},{"code":"HR-4","title":"해운, 잠재적 인력 위기 대응 본격화","src":"Splash 247","date":"2026","kSum":"BIMCO·ICS는 2026년까지 약 9만 명의 추가 사관이 필요하다고 전망했으며 선원 부족은 17년 만의 최고치를 기록했다. 업계가 인력 위기 대응에 나섰다.","eSum":"BIMCO and ICS projected a need for nearly 90,000 additional officers by 2026 with shortages at a 17-year high, prompting the industry to tackle the workforce crisis.","kImp":"사관 인력 부족이 구조적 리스크로 고착.","eImp":"Officer shortages entrenching as a structural risk.","url":"https://splash247.com/shipping-tackles-potential-workforce-crisis/"},{"code":"HR-5","title":"SRI 컨퍼런스 — MLC 미래대비·선원 특별보호","src":"IMO","date":"2026","kSum":"SRI 컨퍼런스에서 MLC의 미래대비와 선원의 핵심노동자(key worker) 지위·공정대우가 논의됐다. 선원 권익 보호 강화가 강조됐다.","eSum":"An SRI conference discussed future-proofing the MLC and special protection for seafarers, including key-worker status and fair treatment, stressing stronger rights protection.","kImp":"선원 핵심노동자 지위 제도화 논의 진전.","eImp":"Progress toward institutionalizing seafarers' key-worker status.","url":"https://www.imo.org/en/mediacentre/secretarygeneral/pages/sri-conference---special-protection-for-seafarers.aspx"},{"code":"HR-6","title":"선원 행복도 하락 — 근로·생활여건 악화","src":"Marine Insight","date":"2026","kSum":"선원 행복도가 근로·생활여건 악화로 하락했다. 정신건강 지원 유용성 평가가 2023년 75%에서 65%로 떨어졌고 괴롭힘 경험이 25%에 달했다.","eSum":"Seafarers' happiness declined as working and living conditions worsened; usefulness of mental-health support fell from 75% (2023) to 65%, and 25% reported harassment.","kImp":"복지·정신건강 투자 실효성 제고 필요.","eImp":"Need to improve the effectiveness of welfare/mental-health support.","url":"https://www.marineinsight.com/shipping-news/seafarers-happiness-declines-as-working-and-living-conditions-worsen-at-sea/"},{"code":"HR-7","title":"3분기 선원 행복지수 전반적 급락","src":"Seatrade Maritime","date":"2026","kSum":"분기 선원 행복지수(Seafarers Happiness Index)가 전 항목에서 급락했다. 임금 정체와 업무 부담 가중에 대한 불만이 반영됐다.","eSum":"The quarterly Seafarers Happiness Index plunged across the board, reflecting frustration with stagnant wages and rising workload.","kImp":"행복지수 악화가 이탈·인력난을 가속할 위험.","eImp":"Falling happiness risks accelerating attrition and shortages.","url":"https://www.seatrade-maritime.com/crewing/seafarer-happiness-plunges-across-the-board-in-q3"},{"code":"HR-8","title":"IMO, 선원 지원 자원·정보 제공","src":"IMO","date":"2026","kSum":"IMO가 선원 지원을 위한 자원·정보를 종합 안내했다. 위기·유기(abandonment) 상황의 선원 보호와 복지 지원 체계를 강조한다.","eSum":"The IMO compiled resources and information for supporting seafarers, emphasizing protection and welfare support in crisis and abandonment situations.","kImp":"선원 유기·위기 대응의 제도적 안전망 강화.","eImp":"Strengthens the institutional safety net for crisis and abandonment.","url":"https://www.imo.org/en/mediacentre/hottopics/pages/supporting-seafarers.aspx"},{"code":"HR-9","title":"'선원의 날'을 넘어 — 지속적 처우 개선 과제","src":"Marine Insight","date":"2026","kSum":"'선원의 날(Day of the Seafarer)'을 계기로 일회성 행사를 넘어선 지속적 처우 개선 필요성이 제기됐다. 핵심노동자로서의 인정과 실질적 복지 강화가 요구된다.","eSum":"Marking the Day of the Seafarer, calls grew for sustained welfare improvement beyond one-off events, with recognition as key workers and tangible support needed.","kImp":"상시적 처우 개선 체계 구축이 과제.","eImp":"Building a continuous welfare-improvement framework is the task.","url":"https://www.marineinsight.com/maritime-law/one-day-for-seafarers-a-lifetime-of-work-ahead/"},{"code":"HR-10","title":"STCW 개정 — 폭력·괴롭힘 예방 교육 의무화 발효","src":"SAFETY4SEA","date":"2026-01-01","kSum":"2026년 1월 1일부로 STCW 코드 개정에 따라 전 선원 대상 해상 폭력·괴롭힘 예방·대응 교육이 의무화됐다. 여성 선원의 괴롭힘 경험률이 50%를 상회하는 현실을 반영했다.","eSum":"From January 1, 2026, amendments to the STCW Code mandate training for all seafarers on preventing and responding to violence and harassment at sea, reflecting that over 50% of female seafarers report harassment.","kImp":"폭력·괴롭힘 예방 교육이 승선 전 필수요건화.","eImp":"Anti-harassment training becomes a pre-boarding requirement.","url":"https://safety4sea.com/cm-maritime-talent-development-program-navigating-the-crew-crisis/"}]},{"code":"HSEQ","kTitle":"Section 10. HSEQ (Health · Safety · Environment · Quality, 10건)","eTitle":"Section 10. HSEQ (Health · Safety · Environment · Quality, 10 items)","type":"news","items":[{"code":"HSEQ-1","title":"North P&I Club, 손실예방 25년 노하우 강화","src":"SAFETY4SEA","date":"2026","kSum":"North P&I Club이 25년간 축적한 손실예방(loss prevention) 노하우를 바탕으로 회원사 사고·클레임 감축 지원을 강화한다고 밝혔다. 데이터 기반 예방 활동을 확대한다.","eSum":"The North P&I Club reaffirmed its commitment to loss prevention built on 25 years of helping members reduce accidents and claims, expanding data-driven prevention.","kImp":"P&I 손실예방 프로그램이 안전관리 보강 수단.","eImp":"P&I loss-prevention programs reinforce safety management.","url":"https://safety4sea.com/north-p-i-club-commits-to-loss-prevention/"},{"code":"HSEQ-2","title":"해양 인텔리전스로 강화되는 P&I 리스크 관리","src":"Hellenic Shipping News","date":"2026","kSum":"해양 인텔리전스가 P&I 클럽의 리스크 관리를 강화하고 있다. 풀 진입 리스크 사전 파악과 객관적 증거 기반 클레임 처리가 핵심으로 부상했다.","eSum":"Maritime intelligence is strengthening P&I club risk management, enabling earlier identification of pool risk and evidence-based claims resolution.","kImp":"데이터 기반 리스크 평가가 보험·안전관리에 확산.","eImp":"Data-driven risk assessment spreads across insurance and safety.","url":"https://www.hellenicshippingnews.com/how-maritime-intelligence-is-strengthening-pi-club-risk-management/"},{"code":"HSEQ-3","title":"EU ETS·FuelEU 2026 — LNG 컴플라이언스의 이중배당","src":"Hellenic Shipping News","date":"2026-01","kSum":"2026년 1월부터 EU ETS 적용범위가 CO₂를 넘어 메탄·아산화질소로 확대되고 배출권 책임이 100%로 상향됐다. FuelEU 첫 정산주기의 보고·검증·벌금이 상반기에 적용된다.","eSum":"From January 2026, EU ETS scope expanded beyond CO₂ to methane and nitrous oxide and moved to 100% allowance liability, while FuelEU's first settlement cycle — reports, verification and penalties — lands in H1 2026.","kImp":"EU 환경규제 강화로 컴플라이언스 비용·관리 부담 급증.","eImp":"Tighter EU rules sharply raise compliance cost and management burden.","url":"https://www.hellenicshippingnews.com/eu-ets-and-fueleu-maritime-the-double-dividend-of-lng-compliance-in-2026/"},{"code":"HSEQ-4","title":"FuelEU Maritime 규정 — 핵심 해설","src":"SAFETY4SEA","date":"2026","kSum":"FuelEU Maritime 규정의 적용범위와 준수 메커니즘이 해설됐다. 연료 온실가스 집약도의 단계적 감축과 풀링·페널티 구조 이해가 필수다.","eSum":"The FuelEU Maritime regulation's scope and compliance mechanisms were explained, stressing the need to understand the gradual GHG-intensity reduction and pooling/penalty structure.","kImp":"연료 GHG 집약도 관리가 운항 의사결정에 직결.","eImp":"Managing fuel GHG intensity directly affects operating decisions.","url":"https://safety4sea.com/cm-fueleu-maritime-regulation-and-insights/"},{"code":"HSEQ-5","title":"국제안전관리(ISM) 코드 — 안전관리체계의 근간","src":"IMO","date":"2026","kSum":"ISM 코드는 선박 안전운항·오염방지의 국제표준으로 모든 선박에 적용되며 안전관리체계(SMS)로 뒷받침된다. 내·외부 심사를 통한 SMS 부적합 관리가 핵심이다.","eSum":"The ISM Code is the international standard for safe ship operation and pollution prevention, applied to all ships and supported by a Safety Management System managed through internal and external audits.","kImp":"SMS 실효성 점검이 HSEQ 관리의 출발점.","eImp":"Verifying SMS effectiveness is the starting point of HSEQ management.","url":"https://www.imo.org/en/ourwork/humanelement/pages/ismcode.aspx"},{"code":"HSEQ-6","title":"선박 안전관리체계(SMS)란 무엇인가","src":"Marine Insight","date":"2026","kSum":"SMS는 모든 선박이 의무 안전규정과 IMO·선급 기준을 준수하도록 보장하는 체계다. 절차서·비상대응·기록관리의 통합 운영이 요구된다.","eSum":"A Safety Management System ensures every ship complies with mandatory safety rules and IMO/class standards, requiring integrated procedures, emergency response and record-keeping.","kImp":"문서화-실행-기록의 일관성이 SMS 신뢰성 좌우.","eImp":"Consistency of documentation, execution and records drives SMS credibility.","url":"https://www.marineinsight.com/marine-safety/what-is-safety-management-system-sms-on-ships/"},{"code":"HSEQ-7","title":"IMO 공식안전평가(FSA) 방법론","src":"IMO","date":"2026","kSum":"공식안전평가(FSA)는 위험식별·평가·통제·비용편익 분석을 통해 규제 의사결정을 지원하는 구조적 방법론이다. 리스크 기반 안전관리의 토대가 된다.","eSum":"Formal Safety Assessment is a structured methodology supporting regulatory decision-making through hazard identification, risk assessment, control and cost-benefit analysis — the basis of risk-based safety management.","kImp":"리스크 기반 접근이 HSEQ 정책 수립의 표준.","eImp":"Risk-based approach is the standard for HSEQ policymaking.","url":"https://www.imo.org/en/ourwork/safety/pages/formalsafetyassessment.aspx"},{"code":"HSEQ-8","title":"Skuld P&I, 화물잔류물 처리 손실예방 안내 (MARPOL Annex V)","src":"SAFETY4SEA","date":"2026","kSum":"Skuld P&I Club이 MARPOL Annex V에 따른 화물잔류물(cargo residues) 처리 손실예방 지침을 발표했다. 부적절한 폐기로 인한 환경위반·벌금 리스크 예방이 목적이다.","eSum":"The Skuld P&I Club issued loss-prevention guidance on disposal of cargo residues in line with MARPOL Annex V, aimed at preventing environmental violations and fines from improper disposal.","kImp":"화물잔류물 관리로 환경 컴플라이언스 리스크 저감.","eImp":"Proper cargo-residue handling reduces environmental compliance risk.","url":"https://safety4sea.com/disposal-of-cargo-residues/"},{"code":"HSEQ-9","title":"2025 해사 규제환경 지형도","src":"Hellenic Shipping News","date":"2026","kSum":"2025~2026 해사 규제환경을 정리한 분석이 공개됐다. EEXI·CII, EU ETS·FuelEU, BWMS 등 복합 규제의 동시 대응이 HSEQ 부서의 핵심 과제로 제시됐다.","eSum":"An analysis charting the 2025-2026 maritime regulatory landscape was published, presenting simultaneous compliance with EEXI/CII, EU ETS/FuelEU and BWMS as the key HSEQ challenge.","kImp":"복합 규제 동시 대응 역량이 HSEQ 경쟁력.","eImp":"Capacity to manage overlapping rules defines HSEQ competence.","url":"https://www.hellenicshippingnews.com/charting-the-2025-maritime-regulatory-landscape/"},{"code":"HSEQ-10","title":"선사 설립에 필요한 ISM 증서","src":"Marine Insight","date":"2026","kSum":"선사 설립·운영에 필요한 ISM 관련 증서(DOC·SMC)와 요건이 정리됐다. 안전관리적합증서(DOC)와 선박안전관리증서(SMC) 유지·갱신이 운항 적격성의 기본이다.","eSum":"The ISM-related certificates (DOC and SMC) and requirements for establishing a shipping company were outlined, with maintaining the Document of Compliance and Safety Management Certificate fundamental to operating eligibility.","kImp":"DOC·SMC 유지가 운항 적격성의 기본 요건.","eImp":"Maintaining DOC/SMC is fundamental to operating eligibility.","url":"https://www.marineinsight.com/marine-safety/what-ism-certificates-you-require-to-start-a-shipping-company/"}]},{"code":"KR","kTitle":"Section 11. 한국해운 시장 (Korean Shipping Market, 10건)","eTitle":"Section 11. Korean Shipping Market (10 items)","type":"news","items":[{"code":"KR-1","title":"HD현대(HD Hyundai), HMM 발주 확정 — 18년 만 최대 컨선 수주","src":"Maritime Executive","date":"2026","kSum":"HD현대(HD Hyundai)가 HMM의 컨테이너선 발주를 확정하며 18년 만 최대 컨선 수주 실적을 달성했다. 한국 조선·해운의 동반 성장 모멘텀을 보여준다.","eSum":"HD Hyundai confirmed an HMM order, achieving its highest containership intake in 18 years and underscoring joint growth momentum for Korean shipbuilding and shipping.","kImp":"한국 해운-조선 수직 협력 강화.","eImp":"Strengthens vertical Korea shipping-shipbuilding cooperation.","url":"https://maritime-executive.com/article/hd-hyundai-confirms-hmm-order-pushes-to-highest-boxship-orders-in-18-years"},{"code":"KR-2","title":"신조 추진 HMM, 中 조선소 검토 논란","src":"한국해운신문 (Korea Maritime Press)","date":"2026","kSum":"HMM이 1만 TEU급 컨선 16척을 2027~2028년 인도 조건으로 신조 추진 중이나, 한국 대비 척당 최소 2천만 달러 저렴한 중국 조선소를 유력 후보로 검토해 논란이 일고 있다.","eSum":"HMM is pursuing 16 boxships (~10,000 TEU) for 2027-2028 delivery, but is reportedly considering Chinese yards — at least USD 20M cheaper per ship than Korean yards — sparking controversy.","kImp":"자국 조선 활용 vs 선가 경쟁력 간 정책 딜레마.","eImp":"Policy dilemma between supporting domestic yards and price competitiveness.","url":"http://www.maritimepress.co.kr/news/articleView.html?idxno=321651"},{"code":"KR-3","title":"HMM, 본점 부산 변경 최종 확정","src":"코리아쉬핑가제트 (KSG)","date":"2026-05-08","kSum":"HMM이 5월 8일 임시주총에서 본사 소재지 정관을 변경해 부산 이전을 최종 확정했다. 이전 등기 후 대표이사 집무실을 우선 이전하고 북항 내 랜드마크 사옥 건립도 추진한다.","eSum":"At a May 8 EGM, HMM amended its articles to relocate headquarters to Busan, planning to move the CEO office first and build a landmark Bukhang HQ building.","kImp":"해운 거점 부산 집중화 정책의 상징적 진전.","eImp":"Symbolic progress in concentrating shipping in Busan.","url":"https://www.ksg.co.kr/news/main_newsView.jsp?pNum=147161"},{"code":"KR-4","title":"HMM, SK해운(SK Shipping) 인수협상 결렬 공시","src":"쉬핑뉴스넷 (Shipping News Net)","date":"2026","kSum":"HMM이 SK해운(SK Shipping) 최종 인수협상 결렬을 공시했다. 대형 M&A를 통한 사업다각화 추진이 일단 무산되며 향후 성장전략 재검토가 예상된다.","eSum":"HMM disclosed the collapse of final acquisition talks for SK Shipping, halting a major diversification M&A and prompting a likely review of its growth strategy.","kImp":"HMM 대형 M&A 성장전략에 제동.","eImp":"A setback to HMM's large-scale M&A growth strategy.","url":"https://www.shippingnewsnet.com/news/articleView.html?idxno=66012"},{"code":"KR-5","title":"해양수산부(MOF) 2026년 예산 7조3,287억 원 편성","src":"해양수산부 (MOF)","date":"2026","kSum":"해양수산부(MOF)가 2026년 예산을 전년 대비 8.1% 증가한 7조3,287억 원으로 편성했다. 부산항 진해신항 예산을 4,622억 원으로 증액하는 등 항만 인프라 투자를 확대했다.","eSum":"Korea's Ministry of Oceans and Fisheries (MOF) set its 2026 budget at KRW 7.33 trillion, up 8.1%, expanding port infrastructure including a raised KRW 462.2B for Busan Jinhae New Port.","kImp":"항만·해양산업 인프라 투자 확대 기조.","eImp":"Continued expansion of port and maritime infrastructure investment.","url":"https://www.mof.go.kr/index.do?menuSeq=1074"},{"code":"KR-6","title":"한국 조선, 2025년 시장점유율 확대","src":"Maritime Executive","date":"2026","kSum":"한국 조선소들이 2025년 시장점유율을 확대했다. 고부가가치 LNG선·방산 수주가 점유율 회복을 견인했다.","eSum":"South Korean shipbuilders achieved market-share gains for 2025, driven by high-value LNG carrier and defense orders.","kImp":"고부가 선종 집중으로 중국 대비 차별화.","eImp":"High-value vessel focus differentiates Korea from China.","url":"https://maritime-executive.com/article/south-korean-shipbuilders-achieve-market-share-gains-for-2025"},{"code":"KR-7","title":"HD한국조선해양, 3개월 만 첫 국내 LNG선 수주","src":"Hellenic Shipping News","date":"2026","kSum":"HD한국조선해양(HD Korea Shipbuilding)이 3개월 만에 첫 국내 LNG 운반선 수주를 확보했다. HD현대삼호가 LNG선 3척을 7억6,950만 달러에 수주하는 등 LNG 수주가 재개됐다.","eSum":"HD Korea Shipbuilding secured its first domestic LNG carrier orders in three months, with HD Hyundai Samho booking three LNG carriers worth USD 769.5M.","kImp":"LNG선 수주 재개로 고부가 수주잔량 확대.","eImp":"Resumed LNG orders expand high-value backlog.","url":"https://www.hellenicshippingnews.com/hd-korea-shipbuilding-secures-first-domestic-lng-carrier-orders-in-three-months/"},{"code":"KR-8","title":"한국 조선, LNG·방산 수주로 3.5년치 일감 확보","src":"Hellenic Shipping News","date":"2026","kSum":"한국 조선소들이 LNG·방산 수주에 힘입어 3.5년치 수주잔량을 확보하고 선가를 끌어올렸다. 2026년 신규 수주의 33%를 LNG선이 주도할 전망이다.","eSum":"Korean shipbuilders secured a 3.5-year backlog as LNG and defense orders lifted prices; LNG carriers are expected to lead 33% of new orders in 2026.","kImp":"풍부한 수주잔량이 선가·수익성 지지.","eImp":"Ample backlog supports prices and profitability.","url":"https://www.hellenicshippingnews.com/korean-shipbuilders-secure-3-5-year-backlog-as-lng-and-defense-orders-lift-prices/"},{"code":"KR-9","title":"한화오션(Hanwha Ocean), LNG선 200척째 인도 — 업계 최초","src":"TradeWinds","date":"2026","kSum":"한화오션(Hanwha Ocean)이 업계 최초로 LNG 운반선 200척째 인도를 달성했다. LNG선 건조 분야의 한국 기술력과 누적 실적을 입증했다.","eSum":"Hanwha Ocean claimed an industry first with delivery of its 200th LNG carrier, validating Korea's technological leadership and track record in LNG carrier construction.","kImp":"LNG선 건조 누적 실적 세계 선두 입지 확인.","eImp":"Confirms global leadership in cumulative LNG carrier construction.","url":"https://www.tradewindsnews.com/gas/hanwha-ocean-claims-shipbuilding-first-with-delivery-of-its-200th-lng-carrier/2-1-1782257"},{"code":"KR-10","title":"中, HMM-현대글로비스(Hyundai Glovis) 최대 자동차선 진수","src":"Maritime Executive","date":"2026","kSum":"중국 조선소가 HMM-현대글로비스(Hyundai Glovis) 협력 사업의 최대 규모 자동차운반선을 진수했다. 한국 선사 주도 친환경 PCTC 선대 확충이 진행 중이다.","eSum":"A Chinese yard launched the largest car carrier for the HMM-Hyundai Glovis partnership, advancing Korean-led green PCTC fleet expansion.","kImp":"한국 선사 자동차물류 경쟁력 강화.","eImp":"Strengthens Korean carriers' vehicle-logistics competitiveness.","url":"https://maritime-executive.com/article/china-launches-largest-car-carrier-for-hmm-hyundai-glovis-partnership"}]},{"code":"INS","kTitle":"Section 12. P&I·H&M 보험 (10건)","eTitle":"Section 12. P&I / H&M Insurance (10 items)","type":"news","items":[{"code":"INS-1","title":"NorthStandard, 2026 연차 호실적 — 보험료 9.38억$ (+5.8%)","src":"NorthStandard","date":"2026","kSum":"NorthStandard가 2026 연차 리뷰에서 2025/26 보험연도 총보험료 9.38억 달러(전년比 5.8%↑)의 견조한 실적과 전략적 모멘텀을 발표했다.","eSum":"NorthStandard reported strong 2026 results with total premium income of US$938m for 2025/26, up 5.8% year-on-year, alongside strategic momentum.","kImp":"대형 합병 P&I 클럽의 안정적 성장 — 담보력·재무건전성 양호.","eImp":"Merged P&I club shows stable growth with sound capacity and finances.","url":"https://north-standard.com/insights-and-resources/resources/press-releases/northstandard-reports-strong-results-and-strategic-momentum"},{"code":"INS-2","title":"UK P&I Club Circular 03/26 — 초과전쟁위험 buy-back $125m 상향","src":"UK P&I Club","date":"2026","kSum":"UK P&I Club 이사회가 초과전쟁위험 P&I 담보 buy-back을 2025/6년 $100m에서 $125m로 상향하고, $1bn 오염 한도와 보충 Bio-Chem 담보를 결의했다. 사이버 전문기관 CyberOwl과 선상 사이버보안 자료도 개발했다.","eSum":"The UK P&I Club board increased the Excess War P&I buy-back to $125m (from $100m in 2025/6), kept the $1bn oil pollution limit and supplementary bio-chem cover, and developed onboard cyber-security materials with CyberOwl.","kImp":"전쟁위험 담보 한도 확대 — 지정학 리스크 대응 강화.","eImp":"Expanded war-risk cover reflects heightened geopolitical risk.","url":"https://www.ukpandi.com/news-and-resources/circulars/article/circular-03/26-update-from-the-board"},{"code":"INS-3","title":"Gard, IG 2026/27 풀링·재보험(GXL) 구조 확정","src":"Gard","date":"2026","kSum":"Gard가 International Group(IG)의 2026/27 정책연도 풀링 및 Group Excess of Loss(GXL) 재보험 계약 구조가 확정됐다고 회원 회람으로 안내했다.","eSum":"Gard advised members that the International Group's Pooling and Group Excess of Loss (GXL) reinsurance structure for the 2026/27 policy year has been finalised.","kImp":"IG 공동재보험 체계 확정 — 클럽 간 위험 분담 안정화.","eImp":"Finalised IG reinsurance stabilises cross-club risk sharing.","url":"https://gard.no/circulars/15-2025-reinsurance-arrangements-for-the-2026-policy-year-arranged-through/"},{"code":"INS-4","title":"Skuld, 2026 P&I Rules 2/20 발효 · 2026/27 갱신 업데이트","src":"Skuld","date":"2026-02-20","kSum":"Skuld의 2026 P&I Rules가 2월 20일부로 발효됐으며, 2026/27 정책연도 갱신 업데이트(Renewal Update 2)가 회원에게 안내됐다.","eSum":"Skuld's 2026 P&I Rules took effect on 20 February, and the 2026/27 policy-year Renewal Update 2 was issued to members.","kImp":"약관 개정·갱신 조건 확인 필요 — 담보 범위 변경 점검.","eImp":"Members should review revised rules and renewal terms for cover changes.","url":"https://www.skuld.com/about/-/circulars/2025/skuld-renewal-update-2-policy-year-202627/"},{"code":"INS-5","title":"The Swedish Club, 2026 선체·기계(H&M) 보험 약관 발표","src":"The Swedish Club","date":"2026","kSum":"The Swedish Club이 2026년 선체·기계(Hull & Machinery) 보험 약관을 발표했다. H&M 담보 조건의 연간 갱신 사항이 정리됐다.","eSum":"The Swedish Club published its 2026 Hull & Machinery insurance terms, setting out the annual update to H&M cover conditions.","kImp":"H&M 약관 갱신 — 선체보험 가입·갱신 시 조건 확인.","eImp":"Updated H&M terms — check conditions at hull cover renewal.","url":"https://www.swedishclub.com/news/circulars/hull-machinery-insurance-terms-2026/"},{"code":"INS-6","title":"West P&I Club, 2025/26 결합비율 98.0%로 개선","src":"West P&I Club","date":"2026","kSum":"West P&I Club의 2025/26 회계연도 결합비율(combined ratio)이 98.0%로 전년 103.9%에서 개선됐다. 자체 클레임이 예상치를 하회하고 풀 클레임 분담도 예산 수준에 근접했다.","eSum":"The West P&I Club's 2025/26 combined ratio improved to 98.0% from 103.9% the prior year, as own claims came in below expectation and Pool claims were near budget.","kImp":"흑자 전환 — 클럽 재무 안정 및 갱신 부담 완화 신호.","eImp":"Return to underwriting profit signals financial stability and easier renewals.","url":"https://www.westpandi.com/news-and-resources/"},{"code":"INS-7","title":"IUMI, 어려운 선체보험 시장·상승하는 리스크 경고","src":"IUMI","date":"2026","kSum":"IUMI가 선체(hull) 보험 시장의 어려움과 상승하는 리스크 수준을 경고했다. 고령 선대·신연료·지정학 요인이 손해율을 압박하고 있다.","eSum":"IUMI highlighted a challenging hull marine insurance market and elevated risk, with an ageing fleet, novel fuels and geopolitics pressuring loss ratios.","kImp":"선체보험 경색 가능성 — 선주 보험료 인상 압박.","eImp":"Possible hull-market hardening may pressure owner premiums.","url":"https://iumi.com/news/press-release/iumi-highlights-challenging-hull-marine-insurance-market-and-elevated-risk/"},{"code":"INS-8","title":"IUMI 통계 2025 — 글로벌 마린 프리미엄 399.2억$ (+1.5%)","src":"IUMI","date":"2026","kSum":"IUMI 2025 통계에 따르면 2024년 글로벌 마린보험 프리미엄은 399.2억 달러로 1.5% 증가했고, 선체(ocean hull) 프리미엄은 96.7억 달러로 3.5% 늘었다. 유럽이 성장세를 주도했다.","eSum":"Per IUMI's 2025 stats, 2024 global marine premiums reached US$39.92bn (+1.5%) and ocean hull premiums US$9.67bn (+3.5%), led by European growth.","kImp":"보험시장 완만한 성장 — 선체 부문 회복세.","eImp":"Modest market growth with recovery in the hull segment.","url":"https://iumi.com/statistics/iumi-stats-report-2025/"},{"code":"INS-9","title":"Cefor, H&M 손해심도 상승 — 기관고장 주도·고령선대 리스크","src":"Cefor","date":"2026-04-13","kSum":"Cefor 분석에 따르면 H&M 손해심도가 코로나 이전을 상회하며 기관(machinery) 고장이 이를 주도하고 있다. 세계 선대 평균 선령 22.6년, 사고의 52%가 20년 이상 선박에서 발생했다. 4/13 웨비나에서 최신 추세를 공개했다.","eSum":"Cefor analysis shows H&M loss severity above pre-COVID levels, led by machinery failures; the world fleet averages 22.6 years and 52% of incidents involved 20-year-plus vessels. Latest trends were shared in an April 13 webinar.","kImp":"기관고장·고령선대 리스크 — 기술팀 PMS·정비 강화 필요.","eImp":"Machinery and ageing-fleet risk calls for stronger PMS and maintenance.","url":"https://cefor.no/statistics/news/webinar-hull-trends"},{"code":"INS-10","title":"P&I보험 기로 — 대형 손해배상청구 증가, 재편 가능성 (Korea P&I)","src":"쉬핑뉴스넷 (Shipping News Net)","date":"2026","kSum":"쉬핑뉴스넷에 따르면 대형 손해배상청구 증가로 P&I보험이 기로에 섰으며 시장 재편 가능성이 제기됐다. Korea P&I Club(한국선주상호보험)도 IG Club 제휴 등으로 대응 기반을 넓히고 있다.","eSum":"Per Shipping News Net, rising large liability claims have put P&I insurance at a crossroads with possible market restructuring; the Korea P&I Club is broadening its base, including IG Club cooperation.","kImp":"대형 클레임 증가 — 한국 선사 P&I 담보·보험료 영향 주시.","eImp":"Rising large claims — watch impact on Korean owners' P&I cover and premiums.","url":"https://www.shippingnewsnet.com/news/articleView.html?idxno=47102"}]}]};